#include <bits/stdc++.h>
using namespace std;

long long cacheDP[105][25][11];
int MOD = 998244353;

long long solveDP(const std::string& A, int index, int prev, int v) {
    if (index == (int)A.size()) {
        return prev == 0 ? 1 : 0;
    }
    if (cacheDP[index][prev][v] != -1) {
        return cacheDP[index][prev][v];
    }
    long long res = 0;
    if (A[index] == '_') {
        for (int j = 0; j < 10; j++) {
            if (index == 0 && j == 0) continue;
            int newPrev = (prev * 10 + j) % 25;
            res += solveDP(A, index + 1, newPrev, v);
        }
    } else if (A[index] == 'X') {
        if (v != 10) {
            res += solveDP(A, index + 1, (prev * 10 + v) % 25, v);
        } else {
            for (int j = 0; j < 10; j++) {
                if (index == 0 && j == 0) continue;
                int newPrev = (prev * 10 + j) % 25;
                res += solveDP(A, index + 1, newPrev, j);
            }
        }
    } else {
        int digit = A[index] - '0';
        res += solveDP(A, index + 1, (prev * 10 + digit) % 25, v);
    }
    return cacheDP[index][prev][v] = res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T = 1;
    while (T > 0) {
        std::string s;
        getline(cin, s);
        std::vector<char> A(s.begin(), s.end());
        if (A.size() == 1 && A[0] == '0') {
            cout << "1\n";
            return 0;
        }
        if (A[0] == '0') {
            cout << "0\n";
            return 0;
        }
        if (A.size() == 1 && (A[0] == 'X' || A[0] == '_')) {
            cout << "1\n";
            return 0;
        }
        for (int i = 0; i <= (int)A.size(); i++) {
            for (int j = 0; j < 25; j++) {
                for (int k = 0; k < 11; k++) {
                    cacheDP[i][j][k] = -1;
                }
            }
        }
        cout << solveDP(A, 0, 0, 10) << "\n";
        T--;
    }
    return 0;
}

